<?php
namespace App\Http\Controllers\Api;
use App\Http\Controllers\Controller;use App\Models\Customer;use Illuminate\Http\Request;
class CustomerController extends Controller {public function index(Request $r){$q=Customer::query();if($s=$r->query('search'))$q->where('customer_name','ilike',"%$s%");$p=$q->orderBy('customer_name')->paginate(min((int)$r->query('per_page',10),100));return response()->json(['success'=>true,'message'=>'OK','data'=>$p->items(),'meta'=>['page'=>$p->currentPage(),'per_page'=>$p->perPage(),'total'=>$p->total(),'total_pages'=>$p->lastPage()]]);}public function store(Request $r){$v=$r->validate(['customer_name'=>'required|string|max:255','customer_address'=>'required|string','gender'=>'required|in:Pria,Wanita','birth_date'=>'nullable|date','phone'=>'nullable|string','email'=>'nullable|email']);return response()->json(['success'=>true,'message'=>'Created','data'=>Customer::create($v)],201);}public function show(Customer $customer){return response()->json(['success'=>true,'message'=>'OK','data'=>$customer]);}public function update(Request $r,Customer $customer){$v=$r->validate(['customer_name'=>'sometimes|required|string','customer_address'=>'sometimes|required|string','gender'=>'sometimes|required|in:Pria,Wanita','birth_date'=>'nullable|date','phone'=>'nullable|string','email'=>'nullable|email']);$customer->update($v);return response()->json(['success'=>true,'message'=>'Updated','data'=>$customer]);}public function destroy(Request $r,Customer $customer){abort_unless($r->user()->isAdmin(),403);$customer->delete();return response()->noContent();}}
